INSERT INTO customer_journey (
    journey_id, case_id, customer_id, customer_name,
    phase, started_at, updated_at
) VALUES (
    #{journeyId}, #{operatingCaseId}, #{customerId}, #{customerName},
    #{phase},
    #{startedAt, typeHandler=com.gien.gits.adapter.persistence.common.typehandler.InstantTypeHandler},
    #{updatedAt, typeHandler=com.gien.gits.adapter.persistence.common.typehandler.InstantTypeHandler}
)

mapper.select:
SELECT journey_id, case_id, customer_id, customer_name,
       phase, started_at, updated_at
FROM customer_journey WHERE journey_id = #{journeyId}

mapper.update:
UPDATE customer_journey SET phase = #{phase},
    updated_at = CURRENT_TIMESTAMP
WHERE journey_id = #{journeyId}

